{"content": "{"question_id": 28, "sql": "SELECT s.School, s.DOC FROM frpm f JOIN schools s ON s.CDSCode = f.CDSCode WHERE s.FundingType = 'Locally funded' AND (f.`Enrollment (K-12)` - f.`Enrollment (Ages 5-17)`) > (SELECT AVG(f2.`Enrollment (K-12)` - f2.`Enrollment (Ages 5-17)`) FROM frpm f2 JOIN schools s2 ON s2.CDSCode = f2.CDSCode WHERE s2.FundingType = 'Locally funded')"}
{"question_id": 36, "sql": "SELECT s.AdmFName1, s.AdmLName1, s.AdmFName2, s.AdmLName2, s.AdmFName3, s.AdmLName3 FROM satscores sa JOIN schools s ON s.CDSCode = sa.cds ORDER BY sa.NumGE1500 DESC LIMIT 1"}
{"question_id": 62, "sql": "SELECT COUNT(*) AS count FROM schools s JOIN frpm f ON f.CDSCode = s.CDSCode WHERE s.County = 'Los Angeles' AND s.Charter = 0 AND f.`Free Meal Count (K-12)` * 100 / f.`Enrollment (K-12)` < 0.18"}
{"question_id": 83, "sql": "SELECT s.City AS City, COUNT(*) AS count FROM frpm f JOIN schools s ON s.CDSCode = f.CDSCode WHERE s.Magnet = 1 AND f.`Low Grade` = 'K' AND f.`High Grade` = '8' AND f.`NSLP Provision Status` = 'Multiple Provision Types' GROUP BY s.City"}
{"question_id": 87, "sql": "SELECT AdmEmail1, AdmEmail2 FROM schools WHERE County = 'San Bernardino' AND City = 'San Bernardino' AND DOC = '54' AND SOC = '62' AND OpenDate BETWEEN '2009-01-01' AND '2010-12-31'"}
{"question_id": 12, "sql": "SELECT MAX(f.`Free Meal Count (Ages 5-17)` / f.`Enrollment (Ages 5-17)`) AS max_ratio FROM satscores sa JOIN frpm f ON f.CDSCode = sa.cds WHERE sa.NumGE1500 * 1.0 / sa.NumTstTakr > 0.3"}
{"question_id": 23, "sql": "SELECT s.School, s.Street FROM frpm f JOIN schools s ON s.CDSCode = f.CDSCode WHERE f.`Enrollment (K-12)` - f.`Enrollment (Ages 5-17)` > 30"}
{"question_id": 24, "sql": "SELECT f.`School Name` FROM frpm f JOIN satscores sa ON sa.cds = f.CDSCode WHERE f.`Free Meal Count (K-12)` / f.`Enrollment (K-12)` > 0.1 AND sa.NumGE1500 > 0"}
{"question_id": 25, "sql": "SELECT sa.sname, f.`Charter Funding Type` FROM satscores sa JOIN frpm f ON f.CDSCode = sa.cds WHERE f.`District Name` LIKE 'Riverside%' AND sa.AvgScrMath > 400"}
{"question_id": 26, "sql": "SELECT f.`School Name`, s.Street, s.City, s.State, s.Zip FROM frpm f JOIN schools s ON s.CDSCode = f.CDSCode WHERE f.`County Name` = 'Monterey' AND f.`School Type` = 'High Schools (Public)' AND f.`FRPM Count (Ages 5-17)` > 800"}
{"question_id": 27, "sql": "SELECT s.School, sa.AvgScrWrite, s.Phone FROM schools s JOIN satscores sa ON sa.cds = s.CDSCode WHERE s.OpenDate > '1991-12-31' OR s.ClosedDate < '2000-01-01'"}
{"question_id": 31, "sql": "SELECT `Free Meal Count (K-12)` / `Enrollment (K-12)` AS ratio FROM frpm ORDER BY `Enrollment (K-12)` DESC LIMIT 2 OFFSET 9"}
{"question_id": 5, "sql": "SELECT COUNT(*) AS count FROM satscores sa JOIN schools s ON s.CDSCode = sa.cds WHERE sa.AvgScrMath > 400 AND s.Virtual = 'F'"}
{"question_id": 11, "sql": "SELECT CDSCode FROM frpm WHERE `Enrollment (K-12)` + `Enrollment (Ages 5-17)` > 500"}
{"question_id": 17, "sql": "SELECT s.CharterNum, sa.AvgScrWrite, RANK() OVER (ORDER BY sa.AvgScrWrite DESC) AS WritingScoreRank FROM satscores sa JOIN schools s ON s.CDSCode = sa.cds WHERE sa.AvgScrWrite > 499 AND s.CharterNum IS NOT NULL"}
